mapper.sql:
WHERE inspection.is_active = 1

  AND DATE(inspection.created) >= #{filter.startDate} AND DATE(inspection.created) <= #{filter.toDate}


  AND inspection.group_id  = #{filter.groupId}


  AND inspection.department_id = #{filter.departmentId}


  AND inspection.department_id IN (SELECT `id` FROM `departments` WHERE `is_active` = 1 AND `province_id` = #{filter.provinceId})


  AND YEAR(inspection.created) = #{filter.year}

mapper.select:
SELECT



ORDER BY inspection.id DESC
LIMIT #{filter.page}, #{filter.rowsPerPage}

mapper.delete:
UPDATE inspection SET
       is_active = 2,
       modified = NOW(),
       modified_by = #{userId}
WHERE id = #{id}
